head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenProcTpCd = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.fr_MktId = $c.lc.fn_getMktId();
scwin.TR_JOB;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const parentWin = $c.frame.path("../");
        vBzProcsNo = parentWin.clickBzProcsNo;
        await scwin.readSync(); // 조회수행
        await scwin.setCode();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07052.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_schdl_dt_onclick
 * @description btn_schdl_dt 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_schdl_dt_onclick = function() {
    try {
        popUpCalendar2(edit_LIST_DELIB_SCHDL_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07052.btn_schdl_dt_onclick" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnLoadCompleted
 * @description dts_EMP_NO 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnLoadCompleted = function(rowcount) {
    try {
        setTimeout("fn_SetCombo()", 300);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07052.dts_EMP_NO_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_examprn_OnLoadError
 * @description dts_examprn 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_examprn_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_examprn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07052.dts_examprn_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_examprn_OnLoadCompleted
 * @description dts_examprn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_examprn_OnLoadCompleted = function(rowcount) {
    try {
        // alert(dts_examprn.NameString(1,"LIST_DELIB_SCHDL_DD"));
        // setObjectValue( edit_LIST_DELIB_SCHDL_DD, dts_examprn.NameString(1,"LIST_DELIB_SCHDL_DD") ) ;
        edit_LIST_DELIB_SCHDL_DD.PutSelClipText(0, 8, dts_examprn.getCellData(1, "LIST_DELIB_SCHDL_DD"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07052.dts_examprn_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07052.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S1');
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07052.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        const selectEmp = cmb_EMP_NO.getValue();
        if ("" !== selectEmp) {
            await scwin.trs();
        } else {
            await $c.win.alert("담당자를 선택해주십시요");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07052.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07052.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange2
 * @description cmb DEP CD onselchange2 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange2 = function() {
    try {
        gDepCd = cmb_DEP_CD.getValue();
        // alert(gDepCd);
        if (gDepCd === '') {
            cmb_EMP_NO.setValue('');
        }
        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
        dts_EMP_NO.sort("DEP_CD", 0);
        // dts_EMP_NO.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07052.cmb_DEP_CD_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselected
 * @description cmb_DEP_CD onselected 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselected = function() {

};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "DEP_CD") === gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07052.dts_EMP_NO_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    gDepCd = js_dep_cd;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // 상장심사팀만 표시
    const vHeadString = "VALUE:STRING(50),TEXT:STRING(50),DEP_CD:STRING(4)";
    // dts_DEP_CD.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_DEP_CD.insertRow();
    dts_DEP_CD.setCellData(1, "VALUE", "");
    dts_DEP_CD.setCellData(1, "TEXT", "전체");
    dts_DEP_CD.setCellData(1, "DEP_CD", "");

    // 유가인 경우 2520, 2540 만 표시
    if ("1" === scwin.fr_MktId) {
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(2, "VALUE", "2520");
        dts_DEP_CD.setCellData(2, "TEXT", "상장심사1팀");
        dts_DEP_CD.setCellData(2, "DEP_CD", "2520");
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(3, "VALUE", "2540");
        dts_DEP_CD.setCellData(3, "TEXT", "상장심사2팀");
        dts_DEP_CD.setCellData(3, "DEP_CD", "2540");
    } else if ("2" === scwin.fr_MktId) {
        // 코스닥인 경우  3320,  3330, 3350 만 표시
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(2, "VALUE", "3320");
        dts_DEP_CD.setCellData(2, "TEXT", "상장심사1팀");
        dts_DEP_CD.setCellData(2, "DEP_CD", "3320");
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(3, "VALUE", "3330");
        dts_DEP_CD.setCellData(3, "TEXT", "상장심사2팀");
        dts_DEP_CD.setCellData(3, "DEP_CD", "3330");

        /*dts_DEP_CD.AddRow();
dts_DEP_CD.setNameString(4, "VALUE","3350") ;
dts_DEP_CD.setNameString(4, "TEXT","상장심사3팀") ;
dts_DEP_CD.setNameString(4, "DEP_CD","3350") ;*/

        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(4, "VALUE", "3E10");
        dts_DEP_CD.setCellData(4, "TEXT", "상장심사1팀(기술)");
        dts_DEP_CD.setCellData(4, "DEP_CD", "3E10");
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(5, "VALUE", "3E20");
        dts_DEP_CD.setCellData(5, "TEXT", "상장심사2팀(기술)");
        dts_DEP_CD.setCellData(6, "DEP_CD", "3E20");
        dts_DEP_CD.insertRow();
        dts_DEP_CD.setCellData(6, "VALUE", "3E30");
        dts_DEP_CD.setCellData(6, "TEXT", "상장심사3팀(기술)");
        dts_DEP_CD.setCellData(6, "DEP_CD", "3E30");
    }
    // cmb_DEP_CD.redraw = true;
    // dts_DEP_CD.Reset();

    if ("1" === scwin.fr_MktId) {
        // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
        const sbmOptions = {
            id : "sbm_dts_EMP_NO",
            action : "/CodeAction.do",
            ref : "",
            target : "dts_EMP_NO=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if ("2" === scwin.fr_MktId) {
        const sbmOptions = {
            id : "sbm_dts_EMP_NO",
            action : "/CodeAction.do",
            ref : "",
            target : "dts_EMP_NO=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (gDepCd.substring(0, 2) === "33") {
            const sbmOptions = {
                id : "sbm_dts_temp",
                action : "/CodeAction.do",
                ref : "",
                target : "dts_temp=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        } else if (gDepCd.substring(0, 2) === "3E") {
            const sbmOptions = {
                id : "sbm_dts_temp",
                action : "/CodeAction.do",
                ref : "",
                target : "dts_temp=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
        dts_EMP_NO.setBroadcast(false);
        for (let i = 2; i <= dts_temp.getRowCount(); i++) {
            /*   alert(dts_temp.NameString(i, "VALUE"));
               alert(dts_temp.NameString(i, "TEXT"));
               alert(dts_temp.NameString(i, "DEP_CD"));*/
            dts_EMP_NO.insertRow();
            if (dts_temp.getCellData(i, "VALUE") !== "") {
                dts_EMP_NO.setCellData(dts_EMP_NO.getRowCount(), "VALUE", dts_temp.getCellData(i, "VALUE"));
                dts_EMP_NO.setCellData(dts_EMP_NO.getRowCount(), "TEXT", dts_temp.getCellData(i, "TEXT"));
                dts_EMP_NO.setCellData(dts_EMP_NO.getRowCount(), "DEP_CD", dts_temp.getCellData(i, "DEP_CD"));
            }
        }
        dts_EMP_NO.setBroadcast(true, true);
        setTimeout("fn_SetCombo()", 500);
    }
    // setTimeout("fn_SetCombo()", 500);

    // alert(dts_examprn.NameString(1,"LIST_DELIB_SCHDL_DD"));

};

/**
         * @method
         * @name readSync
         * @description 조회
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.readSync = async function() {
    // 조회
    url += "&BZ_PROCS_NO=" + vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_examprn",
        action : "/lstinvstg/InvstgAssgn.do",
        ref : "",
        target : "dts_examprn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    const schdlDd = edit_LIST_DELIB_SCHDL_DD.GetSelClipText(0, 8);
    scwin.vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : "U",
    //     EXAMPRN_EMP_NO : $c.stf.getObjectValue(cmb_EMP_NO),
    //     LIST_DELIB_SCHDL_DD : schdlDd,
    //     BZ_PROCS_NO : vBzProcsNo
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/lstinvstg/InvstgAssgn.do",
        ref : "dts_examprn",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCombo
 * @description set Combo 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function() {
    const depCd = dts_examprn.getCellData(1, "DEP_CD");
    // alert(depCd);
    cmb_DEP_CD.setValue(depCd);
    const empNo = dts_examprn.getCellData(1, "EMP_NO");
    // alert(empNo);
    cmb_EMP_NO.setValue(empNo);
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (edt_Bfchg_Std_Ind_Cd.getText() === "") {
        await $c.win.alert("[변경전]데이타가 없어서 처리할수 없습니다.");
        edt_Bfchg_Std_Ind_Cd.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
